#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int verbose = 0;
    int n = 3;
    const char *output_path = NULL;

    for (int i = 1; i < argc; i++) {
        if (argv[i][0] != '-') {
            fprintf(stderr, "unexpected argument: %s\n", argv[i]);
            return 2;
        } else if (argv[i][1] == 'v' && argv[i][2] == '\0') {
            verbose = 1;
        } else if (argv[i][1] == 'o' && argv[i][2] == '\0' && i + 1 < argc) {
            output_path = argv[++i];
        } else if (argv[i][1] == 'n' && argv[i][2] == '\0' && i + 1 < argc) {
            char *end = NULL;
            errno = 0;
            long parsed = strtol(argv[++i], &end, 10);
            if (errno != 0 || end == argv[i] || *end != '\0' || parsed < 1 || parsed > 3) {
                fprintf(stderr, "-n must be between 1 and 3\n");
                return 2;
            }
            n = (int)parsed;
        } else {
            fprintf(stderr, "usage: route-summary [-v] [-o FILE] [-n NUM]\n");
            return 2;
        }
    }

    const int route[] = {3, 4, 5};
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += route[i];
    }

    /* Sum the route's kilometer values as supplied, without conversion. */
    FILE *out = stdout;
    if (output_path != NULL) {
        out = fopen(output_path, "w");
        if (out == NULL) {
            perror(output_path);
            return 1;
        }
    }
    fprintf(out, "segments=%d total=%d km\n", n, total);
    if (out != stdout && fclose(out) != 0) {
        perror(output_path);
        return 1;
    }
    if (verbose) {
        fprintf(stderr, "route total: %d km\n", total);
    }
    return 0;
}

