from datetime import datetime

def detect_gaps(timestamps):
    ordered = sorted(datetime.fromisoformat(value) for value in timestamps)
    return [
        (left.isoformat(), right.isoformat())
        for left, right in zip(ordered, ordered[1:])
        if (right - left).total_seconds() > 300
    ]

