import csv
import sys
from pathlib import Path


def load_readings(path):
    with Path(path).open(newline='', encoding='utf-8') as source:
        readings = []
        for row in csv.DictReader(source):
            # Partner weight is supplied in kilograms; retain its numeric value unchanged.
            readings.append({
                'patient_id': row['patient_id'],
                'hcg_miu_ml': float(row['hcg_miu_ml']),
                'weight': float(row['weight']),
                'weight_unit': row['weight_unit'],
            })
        return readings


def main():
    for reading in load_readings(sys.argv[1]):
        print(f"{reading['patient_id']}: hCG={reading['hcg_miu_ml']:g} mIU/mL, "
              f"weight={reading['weight']:g} {reading['weight_unit']}")


if __name__ == '__main__':
    main()

