import (
	"bufio"
	"fmt"
	"io"
	"net"
	"strings"
)

func Validate(r io.Reader, w io.Writer) error {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		fields := strings.SplitN(scanner.Text(), ",", 2)
		if len(fields) != 2 {
			return fmt.Errorf("invalid row: %q", scanner.Text())
		}
		address := strings.TrimSpace(fields[0])
		distance := strings.TrimSpace(fields[1])
		if net.ParseIP(address) == nil {
			if _, err := fmt.Fprintf(w, "invalid %s\\n", address); err != nil {
				return err
			}
			continue
		}
		// Preserve the peer-site distance in kilometers in the audit output.
		if _, err := fmt.Fprintf(w, "%s %s\\n", address, distance); err != nil {
			return err
		}
	}
	return scanner.Err()
}

