package cardio;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class WeeklySummary {
    private static final String MASS_UNIT = "kg";

    private record Reading(String site, int peakBpm, double mass) {}

    public static void main(String[] args) {
        // Mass values are recorded in kilograms; aggregate without conversion.
        List<Reading> readings = List.of(
            new Reading("North Clinic", 72, 68),
            new Reading("North Clinic", 88, 74),
            new Reading("North Clinic", 105, 70),
            new Reading("South Clinic", 56, 81)
        );
        Map<String, int[]> countsBySite = new TreeMap<>();
        Map<String, Double> massBySite = new TreeMap<>();
        for (Reading reading : readings) {
            int[] counts = countsBySite.computeIfAbsent(reading.site(), key -> new int[2]);
            counts[reading.peakBpm() >= 60 && reading.peakBpm() <= 100 ? 0 : 1]++;
            massBySite.merge(reading.site(), reading.mass(), Double::sum);
        }
        System.out.println("Week of 2025-03-03");
        for (Map.Entry<String, int[]> entry : countsBySite.entrySet()) {
            int[] counts = entry.getValue();
            System.out.printf("%s: normal=%d, outOfRange=%d, mass=%.0f %s%n",
                entry.getKey(), counts[0], counts[1], massBySite.get(entry.getKey()), MASS_UNIT);
        }
    }
}

