function parseLinkHeader(header) {
  const links = {};
  for (const entry of header.split(/,\s*/)) {
    const match = entry.match(/<([^>]+)>;\s*rel="([^"]+)"/);
    if (match) links[match[2]] = match[1];
  }
  return { next: links.next ?? null, prev: links.prev ?? null };
}
module.exports = parseLinkHeader;

