type Config struct {
	ListenAddr      string
	ShipmentWeights []int
	WeightUnit      string
}

type Server struct {
	cfg Config
}

func NewServer(cfg Config) *Server {
	cfg.ShipmentWeights = append([]int(nil), cfg.ShipmentWeights...)
	return &Server{cfg: cfg}
