import requests


class ApiError(RuntimeError):
    pass


class ApiClient:
    def __init__(self, base_url):
        self.base_url = base_url.rstrip("/")

    def catalog(self):
        try:
            response = requests.get(f"{self.base_url}/catalog", timeout=4)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as exc:
            raise ApiError("catalog request failed") from exc

    def nearby(self, radius):
        try:
            response = requests.get(
                f"{self.base_url}/nearby", params={"radius": radius}, timeout=4
            )
            response.raise_for_status()
            return response.json()
        except requests.RequestException as exc:
            raise ApiError("nearby request failed") from exc

